import sys

class NumberTheory:
    class Mod998:
        def __init__(self):
            self.mod = 998244353

        def add(self, a, b):
            return (a + b) % self.mod

        def subtract(self, a, b):
            return (a - b) % self.mod

        def mult(self, a, b, inv_b=None):
            if inv_b is not None:
                return (a * inv_b) % self.mod
            return (a * b) % self.mod

        def smallInv(self, a):
            # Fermat's little theorem for modular inverse
            return pow(a, self.mod - 2, self.mod)

        def fInv(self, n):
            # Placeholder for factorial inverse precomputation if needed
            pass

        def ncr(self, n, r):
            # Placeholder for nCr calculation
            # For simplicity, implement a direct method or precompute factorials
            if r < 0 or r > n:
                return 0
            numerator = 1
            denominator = 1
            for i in range(1, r + 1):
                numerator = (numerator * (n - i + 1)) % self.mod
                denominator = (denominator * i) % self.mod
            return (numerator * self.smallInv(denominator)) % self.mod

class HZSShufflesCards:
    def __init__(self):
        self.mod = NumberTheory.Mod998()

    def solve(self, in_stream, out_stream):
        input_data = sys.stdin.read().split()
        n = int(input_data[0])
        m = int(input_data[1])

        self.mod.fInv(n + m)

        phaseSize = 1
        p = 1
        i = 0
        while p != 0:
            p = self.mod.mult(p, n - i, self.mod.smallInv(n + m - i))
            phaseSize = self.mod.add(phaseSize, p)
            i += 1

        answer = 0
        for k in range(1, n + 1):
            numPhases = self.mod.mult(m + k, self.mod.smallInv(k))
            e = self.mod.mult(numPhases, phaseSize)
            term = self.mod.mult(self.mod.ncr(n, k), e)

            if k % 2 == 1:
                answer = self.mod.add(answer, term)
            else:
                answer = self.mod.subtract(answer, term)

        print(answer, file=out_stream)

if __name__ == "__main__":
    solver = HZSShufflesCards()
    solver.solve(sys.stdin, sys.stdout)

